import {BENCHMARKS,validateBenchmarkReport,summarizeReport} from './benchmarks.js';
import {catalog,dimensions,evidenceFor,reviewedOn,documentSummary} from './technology.js';
import {demo,clone,TYPES,validateState,platformMetrics,scorePlatforms,decision,normalizedMix} from './core.js';
const KEY='basis-iris-production-v1';let s;try{s=JSON.parse(localStorage.getItem(KEY));if(!validateState(s))throw Error('Invalid');}catch{s=clone(demo)}
let page='overview',sub='tasks',filter='All',selected=s.platforms[0]?.id,drawer=false,details=false,notice='';
const $=x=>document.querySelector(x);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const f=(x,d=0)=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});const money=x=>x==null?'—':'$'+f(x,0);const pct=x=>x==null?'—':f(x*100,1)+'%';const safeHref=u=>/^https:\/\/[^\s]+$/i.test(String(u||''))?esc(u):'#';const icon=(n,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="#i-${n}"></use></svg>`;
const icons=`<svg width="0" height="0" style="position:absolute;overflow:hidden"><defs>${Object.entries({play:'<path d="m8 5 11 7-11 7Z"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',finger:'<path d="M12 11v3m-4-2v2a4 4 0 0 0 8 0v-2a4 4 0 1 0-8 0ZM5 13V9a7 7 0 0 1 14 0v4M3 15V9a9 9 0 0 1 18 0v6M12 19v2"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8-9 10-5.5-2-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',flask:'<path d="M9 3h6m-5 0v6l-5.6 9.5A2 2 0 0 0 6 21h12a2 2 0 0 0 1.6-2.5L14 9V3M7 16h10"/>',bars:'<path d="M5 20V10m7 10V4m7 16v-7"/>',scale:'<path d="M12 3v18M5 7h14M5 7 2 13h6L5 7Zm14 0-3 6h6l-3-6ZM8 21h8"/>',brain:'<path d="M12 18V6a4 4 0 0 0-8 0 4 4 0 0 0-1 7 4 4 0 0 0 4 6 4 4 0 0 0 5-1Zm0 0V6a4 4 0 0 1 8 0 4 4 0 0 1 1 7 4 4 0 0 1-4 6 4 4 0 0 1-5-1Z"/>',chev:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',warning:'<path d="m12 3 10 18H2L12 3Zm0 7v4m0 3h.01"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',download:'<path d="M12 3v14m-5-5 5 5 5-5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',trash:'<path d="M4 7h16M10 7V4h4v3m-8 0 1 14h10l1-14M10 11v6m4-6v6"/>',link:'<path d="M10 14a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 10a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M4 5h7a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4zM20 5h-4a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h4z"/>',rotate:'<path d="M3 12a9 9 0 1 0 3-7M3 4v5h5"/>',cross:'<path d="M5 5l14 14m0-14L5 19"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'}).map(([n,d])=>`<g id="i-${n}">${d}</g>`).join('')}</defs></svg>`;
function save(){s.meta.lastUpdated=new Date().toISOString().slice(0,10);localStorage.setItem(KEY,JSON.stringify(s));}function note(t){notice=t;render();setTimeout(()=>{notice='';const n=$('#toast');if(n)n.remove()},3200)}
const nav=[['overview','Home','grid'],['org','Team context','finger'],['gates','Requirements','shield'],['pilot','Tasks & observations','flask'],['results','Results','bars'],['compare','Pilot comparison','bars'],['technology','Tool catalog','book'],['execution','Small test run','play'],['benchmarks','External benchmarks','book'],['judge','Review quality','shield'],['decision','Decision summary','scale'],['settings','Settings','settings']];
const stages=[
 {label:'Set up',icon:'settings',pages:['org','gates','pilot'],hint:'Optional for a quick test. Add team context and requirements when evaluating tools for your organization.'},
 {label:'Run tests',icon:'play',pages:['execution','benchmarks'],hint:'Execution happens in GitHub Actions. Come back here to import the downloaded results.'},
 {label:'Results',icon:'bars',pages:['results','compare','judge','decision'],hint:'Review each evidence source separately. Imported automated results do not become accepted pilot observations.'}
];
function stageFor(id){return stages.find(g=>g.pages.includes(id))}
function sidebarNav(){const items=[['overview','Home','grid'],...stages.map(g=>[g.pages[0],g.label,g.icon]),['technology','Tool catalog','book'],['settings','Settings','settings']];return items.map(([id,label,i],n)=>`${n===4?'<div class="sidetitle nav-resources">RESOURCES</div>':''}<button class="navitem ${(page===id||stageFor(id)?.pages.includes(page))?'active':''}" data-nav="${id}" ${(page===id||stageFor(id)?.pages.includes(page))?'aria-current="page"':''}>${icon(i,18)}<span>${label}</span></button>`).join('')}
function stageNavigation(){const g=stageFor(page);if(!g)return '';return `<div class="stage-navigation"><nav aria-label="${g.label} sections">${g.pages.map(id=>`<button data-nav="${id}" ${id===page?'aria-current="page"':''} class="${id===page?'chosen':''}">${esc(nav.find(n=>n[0]===id)[1])}</button>`).join('')}</nav><p>${g.hint}</p></div>`}
function storedEvidence(){let agent=null,reports=[];try{agent=JSON.parse(localStorage.getItem('basis-latest-agent-result')||'null')}catch{}try{const data=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]');if(Array.isArray(data))reports=data}catch{}return {agent,reports}}

function shell(content){return `${icons}<div class="shell"><aside class="side ${drawer?'show':''}"><div class="brand"><svg class="brand-symbol" aria-hidden="true" viewBox="0 0 48 48"><rect x="1" y="1" width="46" height="46" rx="13" fill="#302843" stroke="#493d60"/><path d="M24 9v30M9 24h30M13.4 13.4l21.2 21.2m0-21.2L13.4 34.6" fill="none" stroke="#bc9cef" stroke-width="3.4"/></svg><div><b>basis<span class="dot">.</span></b><small>ENGINEERING INTELLIGENCE</small></div></div><div class="sidetitle">EVALUATION</div><nav aria-label="Main navigation">${sidebarNav()}</nav><div class="sidebottom"><div class="smallcaps">CURRENT EVALUATION</div><strong>${esc(s.meta.name)}</strong><div class="tiny">${s.platforms.filter(x=>x.enabled).length} candidates · ${s.runs.length} pilot records</div><div class="sideactions"><button title="Export study" data-act="export">${icon('download',16)}</button><button title="Import study" data-act="import">${icon('upload',16)}</button><button title="New empty study" data-act="reset">${icon('rotate',16)}</button></div></div></aside><main class="main"><header class="top"><button class="mobilemenu" data-act="menu" aria-label="Toggle menu">${icon('menu')}</button><div class="crumb">WORKSPACE <span>/</span> ${esc(stageFor(page)?.label||nav.find(x=>x[0]===page)?.[1])}</div><div class="topright"><span class="studyflag ${s.meta.demo?'demo':''}">${s.meta.demo?'● DEMONSTRATION DATA':'● RECORDED DATA (UNVERIFIED)'}</span><button class="helpbtn" data-act="assistant" aria-label="Help">${icon('info',16)} <span>Help</span></button></div></header><div class="workspace">${stageNavigation()}${content}</div><footer>Basis / Evidence before preference <span>Local-first prototype · Study data stays in this browser</span></footer></main></div>${drawer?'<button class="backdrop" data-act="menu" aria-label="Close menu"></button>':''}${notice?`<div id="toast" role="status">${esc(notice)}</div>`:''}<input type="file" id="file-input" accept=".json,application/json" hidden>`}
function title(k,h,desc,action=''){const group=stageFor(page);if(group)k=`0${stages.indexOf(group)+1} / ${group.label.toUpperCase()}`;return `<div class="eyebrow"><span class="pin"></span>${k}</div><div class="pageheading"><div><h1>${h}</h1><p>${desc}</p></div>${action}</div>`}
function platformName(id){return s.platforms.find(p=>p.id===id)?.name||id}function selectOptions(items,v){return items.map(([value,text])=>`<option value="${esc(value)}" ${String(value)===String(v)?'selected':''}>${esc(text)}</option>`).join('')}
function stat(v,l,d){return `<div class="metric"><div class="m-label">${l}</div><strong>${v}</strong><span>${d}</span></div>`}
function overview(){
 const {agent,reports}=storedEvidence(),hasEvidence=!!(s.runs.length||agent||reports.length);
 return title('START HERE','Compare coding tools, step by step.','Basis helps you prepare tests and review their results. Start with a small public coding task to learn how it works.')+`
 <section class="start-panel">
  <div class="start-copy"><span class="miniTag">Suggested first step</span><h2>Try one small coding task</h2><p>Choose an agent, run the included task in your GitHub repository, then bring its result back here.</p><button class="primary" data-nav="execution">Start a small test ${icon('chev',16)}</button><small>Requires a repository with the Basis workflows and a provider API key. API usage may incur costs.</small></div>
  <ol class="start-checklist"><li><span>1</span><div><b>Prepare</b><small>Connect your repository and add a provider key in GitHub.</small></div></li><li><span>2</span><div><b>Run in GitHub</b><small>Select an agent and start the workflow yourself.</small></div></li><li><span>3</span><div><b>Bring back the result</b><small>Download the artifact and import its JSON file into Basis.</small></div></li></ol>
 </section>
 <div class="sectionhead"><h3>Your evaluation workflow</h3><span>Use the sections as you need them.</span></div>
 <div class="journey-grid">
  <button class="journey-card" data-nav="org"><span class="journey-number">01 / SET UP</span><h3>Add your team context</h3><p>Define requirements and your own tasks when you are ready for a broader evaluation.</p><span class="journey-link">Optional for the first test ${icon('chev',16)}</span></button>
  <button class="journey-card" data-nav="execution"><span class="journey-number">02 / RUN TESTS</span><h3>Collect real evidence</h3><p>Start with the small test. External benchmarks are available for larger evaluations.</p><span class="journey-link">Choose a test ${icon('chev',16)}</span></button>
  <button class="journey-card" data-nav="results"><span class="journey-number">03 / RESULTS</span><h3>Review what happened</h3><p>${hasEvidence?'Review your imported reports and recorded observations.':'Results will appear here after you import a report or record a pilot observation.'}</p><span class="journey-link">${hasEvidence?'Open results':'See how results work'} ${icon('chev',16)}</span></button>
 </div>
 <div class="workspace-note">${icon('info',18)}<p><b>What runs where?</b> Basis stores your evaluation in this browser. GitHub Actions runs the coding tools. Nothing starts or spends money when you open this workspace.</p></div>`;
}
function results(){
 const {agent,reports}=storedEvidence();
 return title('03 / REVIEW','Results','Keep automated checks, external benchmarks, and human-reviewed pilot observations distinct.')+`
 ${!agent&&!reports.length&&!s.runs.length?`<section class="empty-results"><span class="empty-icon">${icon('bars',28)}</span><h2>No results yet</h2><p>Run the small test in GitHub Actions, download its artifact, and import <code>agent-result.json</code> on the Small test run page.</p><button class="primary" data-nav="execution">Go to the small test ${icon('chev',16)}</button></section>`:''}
 <div class="journey-grid evidence-sources">
  <article class="panel"><span class="smallcaps">AUTOMATED CHECKS</span><h3>Small test run</h3><p>${agent?`${esc(agent.candidate)} · ${agent.automatedTestsPass?'Checks passed':'Checks failed'}. Human review is still required.`:'No agent result imported. A test pass confirms only the included technical checks.'}</p><button class="secondary" data-nav="execution">${agent?'Inspect imported result':'Import agent result'}</button></article>
  <article class="panel"><span class="smallcaps">EXTERNAL SUITES</span><h3>Benchmark reports</h3><p>${reports.length?`${reports.length} imported report${reports.length===1?'':'s'}. Compare only matching tasks and evaluation conditions.`:'No benchmark reports imported. These are separate from the included small test.'}</p><button class="secondary" data-nav="benchmarks">${reports.length?'View benchmark reports':'Import benchmark report'}</button></article>
  <article class="panel"><span class="smallcaps">TEAM OBSERVATIONS</span><h3>Pilot results</h3><p>${s.runs.length?`${s.runs.length} recorded observation${s.runs.length===1?'':'s'}. Review outcomes, human effort, and modeled costs.`:'No pilot observations recorded. Add results from your own tasks under Set up.'}</p><button class="secondary" data-nav="${s.runs.length?'compare':'pilot'}">${s.runs.length?'Compare pilot results':'Record an observation'}</button></article>
 </div><div class="workspace-note">${icon('shield',18)}<p><b>Making a team-wide decision?</b> Use Pilot comparison, Review quality, and Decision summary above once you have representative observations and reviewed requirements. A small test alone cannot establish a winner.</p></div>`;
}

function org(){const o=s.org;return title('02 / CONTEXT','Team context','Describe the team and workload you want to evaluate. You can skip this for the included small test.',`<button class="secondary" data-act="assistant">${icon('spark',16)} Guided discovery</button>`)+`<div class="split"><div class="panel"><div class="panelheading"><h3>Organization profile</h3><span class="miniTag">Editable</span></div><div class="formgrid"><label>Organization<input data-path="meta.name" value="${esc(s.meta.name)}"></label><label>Engineers<input type="number" min="1" data-path="org.developers" value="${o.developers}"></label><label>Blended hourly cost ($)<input type="number" min="0" data-path="org.rate" value="${o.rate}"></label><label>Monthly AI budget ($)<input type="number" min="0" data-path="org.budget" value="${o.budget}"></label><label>Risk profile<select data-path="org.risk">${selectOptions([['high','High governance'],['medium','Standard governance'],['low','Experimental']],o.risk)}</select></label><label>Repository profile<input data-path="org.repoSize" value="${esc(o.repoSize)}"></label></div><label class="fullfield">Languages / frameworks (comma separated)<input data-path="org.stack" value="${esc(o.stack.join(', '))}"></label><label class="fullfield">Primary objective<textarea data-path="org.objective">${esc(o.objective)}</textarea></label><label class="fullfield">Data boundaries<textarea data-path="org.privacy">${esc(o.privacy)}</textarea></label></div><div class="panel"><div class="panelheading"><h3>Workload signature</h3><span class="miniTag">Adjust the mix</span></div><p class="muted">How is your team's engineering time distributed? These weights drive the task-adjusted comparisons.</p><div class="mixbars">${TYPES.map((t,i)=>`<div class="mixrow"><div class="mixhead"><span><i class="mixdot" style="background:var(--c${i+1})"></i>${t}</span><b data-mix-label="${t}">${s.mix[t]}%</b></div><input aria-label="${t} workload share" type="range" min="0" max="100" data-mix="${t}" value="${s.mix[t]}" style="accent-color:var(--c${i+1})"></div>`).join('')}</div><div class="panelnote" id="mixnote">Normalized for comparison: ${Math.round(Object.values(s.mix).reduce((a,b)=>a+Number(b),0))}% entered (automatically normalized).</div><div class="miniCall">${icon('info',18)} <span>Profile inputs are self-reported unless verified by linked evidence. No repository has been analyzed.</span></div></div></div><div class="panel focus"><h3>Decision priorities</h3><p class="muted">Weights influence exploratory scores. Required gates cannot be overridden by a high score.</p><div class="weightrow">${Object.entries(s.weights).map(([k,v])=>`<label>${k[0].toUpperCase()+k.slice(1)} <input type="number" min="0" max="100" data-weight="${k}" value="${v}"> <small>%</small></label>`).join('')}</div><button class="primary" data-nav="gates">Review requirements ${icon('chev',16)}</button></div>`}
function gates(){return title('03 / TRUST','Requirements','Mandatory controls are pass, fail, or unverified. A score can never override a failed requirement.',`<button class="secondary" data-act="add-gate">${icon('plus',16)} Add requirement</button>`)+`<div class="panel"><div class="table-scroll"><table><thead><tr><th>Requirement</th>${s.platforms.filter(p=>p.enabled).map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${s.gates.map(g=>`<tr><th><span class="gate-title">${icon('shield',16)} ${esc(g.name)}</span><small>${g.required?'Mandatory':'Advisory'} · <button class="inlinebtn" data-act="delete-gate" data-id="${g.id}">Remove</button></small></th>${s.platforms.filter(p=>p.enabled).map(p=>`<td><select class="status ${s.gateResults[p.id]?.[g.id]||'unverified'}" aria-label="${esc(p.name)}: ${esc(g.name)}" data-gate="${p.id}:${g.id}">${selectOptions([['unverified','? Unverified'],['pass','✓ Pass'],['fail','× Fail']],s.gateResults[p.id]?.[g.id]||'unverified')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panelnote">Always attach documentary proof during real evaluation. A marked pass without a verified source is a self-reported claim.</div></div><div class="panel focus"><h3>Requirements checkpoint</h3><div class="statusgrid">${s.platforms.filter(p=>p.enabled).map(p=>{const m=platformMetrics(s,p.id);return `<div class="statusitem"><b>${esc(p.name)}</b><span class="pill ${m.gate}">${m.gate==='pass'?'Controls marked pass':m.gate==='fail'?'Failed requirement':'Unverified controls'}</span></div>`}).join('')}</div><button class="primary" data-nav="pilot">Define your tasks ${icon('chev',16)}</button></div>`}
function pilot(){return title('04 / REAL WORK','Tasks & observations','Define your own pilot tasks and record observations here. The small GitHub test has its own included task and a separate result import.',`<div class="inlineactions"><button class="secondary" data-act="add-task">${icon('plus',16)} Task</button><button class="primary" data-act="add-run" ${s.tasks.length?'':'disabled title="Add a task before recording a result"'}>${icon('plus',16)} Record run</button></div>`)+`<div class="tabs"><button class="${sub==='results'?'chosen':''}" data-sub="results">Pilot runs</button><button class="${sub==='tasks'?'chosen':''}" data-sub="tasks">Task library</button><button class="${sub==='method'?'chosen':''}" data-sub="method">Study protocol</button></div>${sub==='results'?`<div class="panel"><div class="panelheading"><h3>Evidence log</h3><div><select data-filter="runs"><option>All</option>${s.platforms.map(p=>`<option ${filter===p.id?'selected':''} value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div></div><div class="table-scroll"><table><thead><tr><th>Task & platform</th><th>Accepted</th><th>Human time</th><th>Usage cost</th><th>Evidence</th><th></th></tr></thead><tbody>${s.runs.filter(r=>filter==='All'||r.platform===filter).map(r=>`<tr><td><b>${esc(platformName(r.platform))}</b><small>${esc(s.tasks.find(x=>x.id===r.task)?.name||r.task)}</small></td><td><span class="pill ${r.accepted?'pass':'fail'}">${r.accepted?'Accepted':'Not accepted'}</span></td><td>${f(r.humanMinutes)} min</td><td>${money(r.usageCost)}</td><td>${r.evidence?`<a href="${safeHref(r.evidence)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:'<span class="dim">Not linked</span>'}</td><td><button class="iconbtn" title="Delete record" aria-label="Delete run" data-act="delete-run" data-id="${esc(r.id)}">${icon('trash',15)}</button></td></tr>`).join('')}</tbody></table></div></div>`:sub==='tasks'?`${s.tasks.length?'':'<div class="empty"><b>No pilot tasks yet</b><p>Add a task with acceptance criteria to begin a team pilot. To try the included public task, use Run tests instead.</p></div>'}<div class="taskgrid">${s.tasks.map(t=>`<div class="panel task"><div class="smallcaps">${esc(t.id)} · ${esc(t.type)}</div><h3>${esc(t.name)}</h3><p>${esc(t.acceptance)}</p><div class="taskbottom"><span>${esc(t.difficulty)} · ${f(t.baseline)} min baseline</span><button class="iconbtn" data-act="delete-task" data-id="${t.id}" title="Delete task">${icon('trash',16)}</button></div></div>`).join('')}</div>`:`<div class="panel prose"><h3>Recommended study protocol</h3><p>Pre-register task acceptance rules and safeguards. Use real representative tasks with comparable starting conditions, equal access to documentation, and balanced assignments across developers.</p><div class="protocol">${[['01','Build a baseline','Capture no-tool or current-tool human effort and accepted outcomes.'],['02','Randomize fairly','Balance task complexity, developer experience and tool familiarity.'],['03','Validate independently','Run executable tests, peer reviews, security checks and follow-up.'],['04','Preserve failures','Count unsuccessful attempts, retries, waiting, review and rescue work.'],['05','Calibrate inference','Report sampling uncertainty, missing outcomes and the smallest useful improvement.']].map(([n,t,d])=>`<div><span>${n}</span><b>${t}</b><small>${d}</small></div>`).join('')}</div></div>`}<div class="panel focus"><div class="panelheading"><h3>Evidence hygiene</h3><span>${s.runs.filter(r=>r.evidence).length}/${s.runs.length} runs with linked sources</span></div><p class="muted">A platform cannot receive a procurement-ready recommendation solely from synthetic examples, unchecked declarations, or a small biased pilot.</p><button class="primary" data-nav="compare">Compare measured results ${icon('chev',16)}</button></div>`}
function compare(){const arr=scorePlatforms(s),choices=s.platforms.filter(p=>p.enabled);const selectedId=choices.some(p=>p.id===selected)?selected:choices[0]?.id;selected=selectedId;const chosen=arr.find(x=>x.id===selectedId);return title('05 / ANALYZE','Pilot comparison','Explore how each candidate performs on your workload. Recompute results as assumptions change.',`<div class="inlineactions"><button class="secondary" data-act="manage-platforms">${icon('settings',16)} Candidates</button><button class="secondary" data-nav="decision">Decision summary ${icon('chev',16)}</button></div>`)+`<div class="comparecontrols"><div class="pillgroup">${choices.map(p=>`<button class="${selectedId===p.id?'active':''}" data-platform="${p.id}">${esc(p.name)}</button>`).join('')}</div><span class="miniTag">Workload-normalized pilot data</span></div><div class="metrics">${stat(chosen?pct(chosen.success):'—','Accepted task rate','Weighted for your workload')}${stat(chosen?f(chosen.effort,0)+'m':'—','Human effort','Per accepted task')}${stat(chosen?money(chosen.fullCost):'—','Full cost','Per accepted task · modeled')}${stat(chosen?pct(chosen.coverage):'—','Workload coverage','Tested task-family share')}</div><div class="split"><div class="panel"><div class="panelheading"><h3>Quality by work type</h3><span class="miniTag">Pass rate</span></div>${TYPES.map((t,i)=>{const r=chosen?.byType[t];return `<div class="barrow"><div class="barlabel"><span>${t}</span><b>${pct(r?.success)}</b></div><div class="track"><span style="width:${r?.success==null?0:r.success*100}%;background:var(--c${i+1})"></span></div><small>${r?.n||0} trial records</small></div>`}).join('')}<div class="panelnote">Small samples are unstable. Empty categories are missing evidence, not zero performance.</div></div><div class="panel"><div class="panelheading"><h3>Cost sensitivity</h3><span class="miniTag">What if?</span></div><p class="muted">Adjust the blended hourly labor rate. All shown cost models update together.</p><div class="bigslider"><div class="rangevalue"><span>Hourly labor</span><strong id="rate-label">$${f(s.org.rate)}</strong></div><input type="range" min="20" max="250" step="5" data-range="org.rate" value="${s.org.rate}"></div><div class="costlist">${arr.map(m=>`<div class="costitem"><span>${esc(platformName(m.id))}</span><div class="costtrack"><i style="width:${m.fullCost!=null?Math.max(3,Math.min(100,m.fullCost/Math.max(...arr.map(x=>x.fullCost||0),1)*100)):0}%"></i></div><b>${money(m.fullCost)}</b></div>`).join('')}</div><p class="panelnote">Model includes measured per-attempt usage + labor + illustrative allocated platform overhead. Configure overhead in assumptions.</p></div></div><div class="panel"><div class="panelheading"><h3>All-candidate results</h3><button class="subtle" data-act="toggle-details">${details?'Hide scoring':'Show scoring method'} ${icon('down',15)}</button></div><div class="table-scroll"><table><thead><tr><th>Platform</th><th>Accepted</th><th>Effort / accepted</th><th>Cost / accepted</th><th>Gate</th><th>Evidence</th></tr></thead><tbody>${arr.map(m=>`<tr><td><b>${esc(platformName(m.id))}</b></td><td>${pct(m.success)}</td><td>${m.effort==null?'—':f(m.effort,0)+' min'}</td><td>${money(m.fullCost)}</td><td><span class="pill ${m.gate}">${m.gate}</span></td><td>${m.evidence.linked}/${m.evidence.total} linked</td></tr>`).join('')}</tbody></table></div>${details?`<div class="panelnote">Weights: ${Object.entries(s.weights).map(([k,v])=>`${k} ${v}`).join(' · ')}. Scores are relative exploratory indicators, not validated rankings. Missing work types and synthetic evidence disqualify candidates from a final recommendation.</div>`:''}</div>`}
function judge(){const discrepancy=s.judgments.filter(j=>j.scoreA!==j.scoreB).length;return title('06 / ASSURANCE','Review quality','LLM opinions are supplementary. Inspect conflicts, stability, and calibration before trusting subjective assessments.',`<button class="secondary" data-act="add-judgment">${icon('plus',16)} Add blind judgment</button>`)+`<div class="hero compact"><div class="hero-copy"><div class="hero-tag">${icon('shield',15)} INDEPENDENCE FIRST</div><h2>No model gets to pick its own winner.</h2><p>Blind labels, counterbalanced order, independent review and an auditable decision engine.</p></div><div class="integrity-symbol">${icon('scale',72)}</div></div><div class="metrics">${stat(s.judgments.length,'Recorded judgments','Blind assessment entries')}${stat(discrepancy,'Judge disagreements','Require adjudication')}${stat(s.judges.filter(j=>j.calibrated).length+'/'+s.judges.length,'Calibrated judges','Verified against human cases')}${stat('0','Auto overrides','The judge cannot bypass gates')}</div><div class="split"><div class="panel"><div class="panelheading"><h3>Assessment guardrails</h3></div>${[['eye-off','Mask vendor identity','Blind code evaluation where technically possible.'],['rotate','Counterbalance ordering','Review both A/B and B/A orderings.'],['shield','Run objective checks first','Tests and security outcomes outrank model preference.'],['finger','Version every decision','Preserve rubric, judge model, prompt, and reviewer action.']].map(([ic,t,d],i)=>`<div class="guard"><span class="guardnum">0${i+1}</span><span><b>${t}</b><small>${d}</small></span>${icon('check',16)}</div>`).join('')}</div><div class="panel"><div class="panelheading"><h3>Judge registry</h3></div>${s.judges.map(j=>`<div class="judgerow"><div class="avatar">${icon('brain',18)}</div><div><b>${esc(j.name)}</b><small>${esc(j.family)}</small></div><span class="pill ${j.calibrated?'pass':'unverified'}">${j.calibrated?'Calibrated':'Not calibrated'}</span></div>`).join('')}<div class="panelnote">Do not treat a multi-model vote as a guarantee of neutrality. Calibrate using independent, expert-reviewed code samples.</div></div></div><div class="panel"><div class="panelheading"><h3>Blind review records</h3></div>${s.judgments.length?`<div class="table-scroll"><table><thead><tr><th>Case</th><th>Judge A</th><th>Judge B</th><th>Reviewer verdict</th></tr></thead><tbody>${s.judgments.map(j=>`<tr><td>${esc(j.caseName)}</td><td>${j.scoreA}/5</td><td>${j.scoreB}/5</td><td>${esc(j.review||'Pending')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No judgment records yet. Add an assessment and independently calibrate it before using it as evidence.</div>'}</div>`}
function decisionPage(){const d=decision(s),arr=d.ranked;return title('07 / DECISION','Decision summary','Make a choice only when quality, governance, cost, and evidence withstand scrutiny.',`<div class="inlineactions"><button class="secondary" data-act="export">${icon('download',16)} Export study</button></div>`)+`<div class="hero decisionhero"><div class="hero-copy"><div class="hero-tag">${icon('scale',15)} REPRODUCIBLE DECISION ENGINE</div><h2>${esc(d.heading)}</h2><p>${esc(d.reason)}</p><span class="pill ${d.type==='insufficient'?'unverified':'pass'}">${d.type==='insufficient'?'Evidence required':d.type==='tie'?'Review required':'Conditional only'}</span></div><div class="integrity-symbol">${icon('target',72)}</div></div><div class="split"><div class="panel"><div class="panelheading"><h3>Readiness by platform</h3></div>${arr.map(m=>`<div class="readyrow"><span><b>${esc(platformName(m.id))}</b><small>${m.n} records · ${m.evidence.linked} linked · ${pct(m.coverage)} workload coverage</small></span><span class="pill ${m.eligible?'pass':m.gate==='fail'?'fail':'unverified'}">${m.eligible?'Eligible':m.gate==='fail'?'Blocked':'Not ready'}</span></div>`).join('')}</div><div class="panel"><div class="panelheading"><h3>What is needed next</h3></div>${[['shield','Verify mandatory controls','Attach security, legal and access-control evidence.'],['link','Source your test results','Replace demonstrations with auditable pilot records.'],['flask','Run balanced work samples','Expand difficult task types and track downstream defects.'],['brain','Calibrate subjective judges','Use human-reviewed references and bias checks.']].map(([ic,t,d])=>`<div class="guard"><span class="avatar">${icon(ic,16)}</span><span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div></div><div class="panel focus"><h3>Decision policy</h3><p class="muted">A vendor becomes eligible only when all mandatory requirements are marked pass, every active work type has pilot records, there are at least five recorded runs, at least 70% of those runs have evidence links, and the study is no longer marked as demonstration data. These minimums are prototype guardrails, not statistical proof of superiority.</p><button class="primary" data-act="mark-real">${s.meta.demo?'Review converting demo to real':'Study already marked as real'} ${icon('chev',16)}</button></div>`}
function technology(){const summary=documentSummary();return title('06 / OFFICIAL DOCUMENTATION','Tool catalog','Vendor capabilities, with primary-source links and explicit evidence status. Documentation is not an independent product test.',`<span class="miniTag">Reviewed ${reviewedOn}</span>`)+`<div class="metrics">${stat(summary.platforms,'Catalog entries','Named vendor configurations')}${stat(summary.documentedClaims,'Sourced claims','Vendor documentation only')}${stat(summary.independentlyVerifiedClaims,'Independently verified','Needs integration tests')}${stat(dimensions.length,'Capability groups','Unknown is not unsupported')}</div><div class="panel"><div class="panelheading"><h3>Documentation evidence</h3><small>Click each cited claim for the vendor source ↗</small></div><div class="tech-scroll"><table class="tech-table"><thead><tr><th>Capability</th>${s.platforms.filter(p=>p.enabled).map(p=>`<th>${esc(p.name)}<small>${esc(p.mode)}</small></th>`).join('')}</tr></thead><tbody>${dimensions.map(d=>`<tr><th>${icon(d.icon,16)} ${esc(d.label)}</th>${s.platforms.filter(p=>p.enabled).map(p=>{const cs=evidenceFor(p.id,d.id);return `<td>${cs.length?cs.map(c=>`<a target="_blank" rel="noopener noreferrer" href="${safeHref(c.source)}" title="Open official documentation"><span class="source-dot">● Documented ↗</span><small>${esc(c.claim)}</small></a>`).join(''):'<span class="unknown">? Not researched</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="panelnote">“Documented” means a vendor currently describes the capability; it does not imply it was tested in your configuration. Unknown means not yet researched, not absent. Claims must be rechecked before procurement.</div></div><div class="split"><div class="panel"><div class="panelheading"><h3>How to use this evidence</h3></div><div class="guard"><span class="avatar">${icon('book')}</span><span><b>Read the claim</b><small>Open the primary source, confirm plan, model, version and restrictions.</small></span></div><div class="guard"><span class="avatar">${icon('flask')}</span><span><b>Verify in your environment</b><small>Run a controlled demonstration and record observations under Set up → Tasks &amp; observations.</small></span></div></div><div class="panel"><div class="panelheading"><h3>Source health</h3></div><p class="muted">Last editorial review: ${reviewedOn}. Automated link checks run in GitHub Actions; live vendor content is not silently converted into approved claims.</p><p class="muted">Technical requirements remain governed by the mandatory controls in Set up → Requirements.</p><button class="secondary" data-nav="gates">Review requirements ${icon('chev',16)}</button></div></div>`;}
function execution(){
 const {agent:rec}=storedEvidence();
 const repo=localStorage.getItem('basis-evaluation-repo')||'';
 return title('02 / RUN TESTS','Small test run','Run the included public coding task with one agent. Use this to check the execution pipeline before attempting a larger benchmark.')+`
 <div class="run-location">${icon('info',18)}<span><b>Runs in GitHub Actions.</b> Basis opens the workflow; you choose the agent and confirm the run in GitHub. Results are imported manually.</span></div>
 <div class="run-step panel"><span class="step">1</span><div class="run-step-content"><h2>Prepare your repository</h2><p>Use a repository containing the Basis workflows. If you have not set one up, <a href="https://github.com/PouyanJay/basis/fork" target="_blank" rel="noopener noreferrer">fork Basis on GitHub ↗</a> and enable Actions in your fork.</p><label class="fullfield">Evaluation repository<input id="evaluation-repo" placeholder="your-account/basis" value="${esc(repo)}" autocomplete="off" spellcheck="false"></label><p>Add the provider key under <b>Settings → Secrets and variables → Actions</b> in that repository.</p><details class="provider-help"><summary>Which key does my agent need?</summary><ul><li>Codex: <code>OPENAI_API_KEY</code></li><li>Claude Code: <code>ANTHROPIC_API_KEY</code></li><li>Cursor: <code>CURSOR_API_KEY</code></li><li>OpenCode: the key for your chosen OpenAI or Anthropic model.</li></ul></details><button class="secondary" data-act="open-run-secrets">Open repository secrets ↗</button></div></div>
 <div class="run-step panel"><span class="step">2</span><div class="run-step-content"><h2>Start the test in GitHub</h2><p>Open the workflow, select <b>Run workflow</b>, choose your agent and optional model, and confirm the public fixture. OpenCode requires a <code>provider/model</code> value.</p><button class="primary" data-act="open-fixture-actions">Open test workflow ↗</button><p class="panelnote">Provider API usage may incur costs. This small task checks the integration, not which tool is best. Live provider compatibility still requires validation in your environment.</p><p id="run-guidance" role="status"></p></div></div>
 <div class="run-step panel"><span class="step">3</span><div class="run-step-content"><h2>Import the result</h2><p>When the workflow finishes, open its <b>Artifacts</b> section. Download and unzip the <code>basis-[agent]-[run-id]</code> artifact, then select <code>agent-result.json</code> below.</p><button class="secondary" data-act="import-agent">${icon('upload',16)} Import agent-result.json</button><input type="file" id="agent-file" accept="application/json,.json" hidden><p class="panelnote">If no artifact was produced, inspect the failed step in GitHub. Basis does not monitor jobs or retrieve artifacts automatically.</p></div></div>
 ${rec?`<section class="panel"><div class="panelheading"><h3>Last imported small test</h3><span class="pill unverified">Unverified import</span></div><p>${esc(rec.candidate)} · ${rec.automatedTestsPass?'Automated checks passed':'Automated checks failed'} · ${f(rec.elapsedSeconds,1)} seconds</p><p class="muted">Model: ${esc(rec.model)}. Task SHA-256: ${esc(rec.taskDigest)}. Automated checks do not establish independent acceptance.</p><button class="secondary" data-nav="results">Review results ${icon('chev',16)}</button></section>`:'<p class="panelnote">No agent result imported yet. Once imported, it will also be listed under Results.</p>'}`;
}

const secretProviders=[
 {id:'claude',name:'Claude Code',secret:'ANTHROPIC_API_KEY',hint:'Anthropic API key'},
 {id:'cursor',name:'Cursor',secret:'CURSOR_API_KEY',hint:'Cursor API key'},
 {id:'codex',name:'OpenAI Codex',secret:'OPENAI_API_KEY',hint:'OpenAI API key'},
 {id:'opencode',name:'OpenCode',secret:'',hint:'Uses the underlying model provider key (OpenAI / Anthropic)'},
 {id:'devin',name:'Devin',secret:'DEVIN_API_KEY',hint:'Reserved for future runner integration'},
 {id:'xai',name:'xAI / Grok',secret:'XAI_API_KEY',hint:'Reserved for future runner integration'}
];
function settings(){return title('10 / CREDENTIALS','Provider credentials','Configure GitHub Actions secrets without exposing keys in your Pages deployment.')+`<div class="panel credential-intro"><div class="panelheading"><h3>Private by design</h3><span class="pill unverified" id="bridge-label">Checking local companion…</span></div><p class="muted">Keys never enter your Basis study, browser storage, export, or repository. To submit them, open this app through the optional local companion, authenticated with GitHub CLI. On GitHub Pages, the fields remain disabled.</p><div class="credential-actions"><a href="https://cli.github.com/manual/gh_auth_login" target="_blank" rel="noopener noreferrer">GitHub CLI setup ↗</a><button class="secondary" type="button" id="bridge-recheck">Check connection</button></div><p class="tiny">Start locally: <code>python3 scripts/credential_companion.py</code>. Then open the printed localhost address. Run <code>gh auth login</code> beforehand.</p></div><div class="panel"><div class="panelheading"><h3>GitHub destination</h3><span class="miniTag">Actions repository secrets</span></div><label class="credentials-repo-label">Repository (owner/repo)<input id="secret-repo" autocomplete="off" spellcheck="false" placeholder="organization/basis-evaluation" maxlength="100" /></label><p class="panelnote">Use the private evaluation runner repository, not a public source repository for results.</p></div><div class="credential-list">${secretProviders.map(p=>`<div class="panel credential-card"><div class="credential-head"><div><strong>${esc(p.name)}</strong><small>${esc(p.hint)}</small></div><span class="credential-indicator">${p.secret?'Not verified':'Uses provider keys'}</span></div>${p.secret?`<label class="credentials-key-label" for="key-${p.id}">${esc(p.secret)}</label><div class="credential-form"><input type="password" id="key-${p.id}" data-secret-input autocomplete="new-password" disabled placeholder="Start local companion to enter key" aria-label="${esc(p.name)} secret" /><button class="secondary" data-secret-toggle="${p.id}" disabled type="button">Show</button><button class="primary" data-secret-save="${p.id}" disabled type="button">Save securely</button></div><p class="credential-feedback" id="result-${p.id}" role="status" aria-live="polite"></p>`:`<p class="muted">Choose a model provider in the execution workflow and configure its corresponding key above.</p>`}</div>`).join('')}</div><div class="panelnote">GitHub encrypts Actions secrets at rest; after submission the site cannot read the stored values. Connection health does not reveal which secrets exist. Only the four implemented runners can execute today.</div>`;}
let bridgeReady=false;let bridgeToken='';
async function checkBridge(){const label=$('#bridge-label');if(!label)return;bridgeReady=false;bridgeToken='';try{if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('Not running locally');let r=await fetch('/api/health',{cache:'no-store'});let j=await r.json();if(!r.ok||j.service!=='basis-credential-companion'||typeof j.token!=='string')throw Error('Unavailable');bridgeReady=true;bridgeToken=j.token;}catch{}label.textContent=bridgeReady?'Local companion connected':'Open via local companion';label.className='pill '+(bridgeReady?'pass':'unverified');document.querySelectorAll('[data-secret-input],[data-secret-save],[data-secret-toggle]').forEach(e=>e.disabled=!bridgeReady);}
async function submitSecret(id){const p=secretProviders.find(x=>x.id===id);if(!p?.secret||!bridgeReady)return;const input=$('#key-'+id),out=$('#result-'+id),repo=$('#secret-repo')?.value.trim();if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo||'')){out.textContent='Enter a valid owner/repo first.';return}if(!input.value||/[\r\n]/.test(input.value)){out.textContent='Enter a single-line API key.';return}const value=input.value;input.value='';out.textContent='Submitting to GitHub Actions Secrets…';try{const res=await fetch('/api/secrets',{method:'POST',headers:{'Content-Type':'application/json','X-Basis-Token':bridgeToken},body:JSON.stringify({repo,secret:p.secret,value})});const json=await res.json();out.textContent=res.ok?'Saved to GitHub Actions Secrets. Value is no longer accessible here.':(json.error||'Unable to save.');}catch{out.textContent='Local companion unavailable. The key was not retained.'}}
function bindCredentials(){checkBridge();$('#bridge-recheck')?.addEventListener('click',checkBridge);document.querySelectorAll('[data-secret-save]').forEach(b=>b.addEventListener('click',()=>submitSecret(b.dataset.secretSave)));document.querySelectorAll('[data-secret-toggle]').forEach(b=>b.addEventListener('click',()=>{let input=$('#key-'+b.dataset.secretToggle);if(input.type==='password'){input.type='text';b.textContent='Hide'}else{input.type='password';b.textContent='Show'}}));}
function benchmarks(){
 let rows=[];try{rows=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]')}catch{}
 const config=JSON.parse(localStorage.getItem('basis-swe-config')||'{"percent":10,"seed":"42","agents":["codex"]}');
 const opts=[5,10,25,50,100].map(v=>`<button type="button" data-swe-pct="${v}" class="${config.percent===v?'active':''}">${v===100?'Full · 300':v+'% · '+Math.ceil(v*3)}</button>`).join('');
 const agentOptions=['codex','claude','cursor','opencode'].map(a=>`<label class="swe-agent"><input type="checkbox" data-swe-agent="${a}" ${config.agents.includes(a)?'checked':''}> ${a==='codex'?'Codex':a==='claude'?'Claude Code':a==='cursor'?'Cursor':'OpenCode'}</label>`).join('');
 const box=`<section class="panel swe-studio"><div class="panelheading"><h3>${icon('flask',18)} SWE-bench Lite · Run studio</h3><span class="miniTag">Official test split · 300 tasks</span></div><p class="muted">1 · Choose a reproducible sample. 2 · Select agents. 3 · Launch in GitHub Actions. 4 · Import genuine official-harness results.</p><div class="swe-columns"><div><label class="swe-label">Sample size</label><div class="pillgroup swe-preset">${opts}</div><label class="swe-label" for="swe-custom">Custom percentage</label><input id="swe-custom" type="number" min="1" max="100" step="1" value="${config.percent}"><p class="panelnote" id="swe-count">${Math.ceil(config.percent*3)} of 300 tasks · repo-balanced nested sample</p><label class="swe-label" for="swe-seed">Random seed</label><input id="swe-seed" maxlength="40" value="${esc(config.seed)}" aria-label="Random seed"><p class="panelnote">The same seed gives every agent the same selected tasks. Larger percentages include the smaller sample.</p></div><div><label class="swe-label">Coding agents</label><div class="swe-agents">${agentOptions}</div><p class="panelnote">Provider credentials are configured in Settings. API usage and Docker grading may incur significant costs.</p><label class="swe-label" for="swe-repo">Evaluation repository</label><input id="swe-repo" placeholder="owner/repository" value="${esc(config.repo||localStorage.getItem('basis-evaluation-repo')||'')}" autocomplete="off" spellcheck="false"><div class="bench-actions"><button class="primary" data-act="open-swe-actions">${icon('play',16)} Open GitHub Actions ↗</button><button class="secondary" data-act="download-swe-config">${icon('download',16)} Download run configuration</button></div><p class="panelnote" id="swe-guidance">GitHub Pages cannot securely start paid runners directly. The workflow launches from GitHub Actions using the same selections.</p></div></div></section>`;
 return title('02 / RUN TESTS','External benchmarks','Standard, externally maintained suites. Pick a benchmark, run its official harness, and bring the evidence back to Basis.')+box+
 `<div class="benchmark-grid">${BENCHMARKS.map((b,i)=>`<article class="panel benchmark-tile"><div class="panelheading"><h3>${esc(b.name)}</h3><span class="miniTag">Official suite</span></div><div class="muted">${esc(b.category)} · ${esc(b.difficulty)}</div><p>${esc(b.note)}</p><div class="panelnote">${esc(b.runner)}<br>${esc(b.runtime)}</div><div class="bench-actions"><a href="${b.setup}" target="_blank" rel="noopener noreferrer" class="secondary">Run instructions ↗</a><a href="${b.source}" target="_blank" rel="noopener noreferrer" class="textaction" aria-label="Official source ${esc(b.name)}">Source ↗</a></div></article>`).join('')}</div>`+
 `<div class="panel"><div class="panelheading"><h3>Import standardized evidence</h3><span class="miniTag">Not automatically verified</span></div><p class="muted">Run the official benchmark harness externally; normalize its authentic task outcomes to the Basis v1 report schema. Importing does not certify that the claimed agent or harness was used.</p><div class="bench-actions"><button class="primary" data-act="import-benchmark">${icon('upload',16)} Import benchmark report</button><button class="secondary" data-act="download-benchmark-template">${icon('download',16)} Download report template</button></div><input type="file" id="benchmark-file" accept="application/json,.json" hidden><div class="panelnote">Scores are only comparable for exactly matching dataset revisions, harness revisions, evaluation conditions and task sets. Existing toy-agent runs are not community benchmark runs.</div></div>`+
 (rows.length?`<div class="panel"><div class="panelheading"><h3>Imported reports</h3><span class="miniTag">Self-reported · Unverified</span></div><div class="table-scroll"><table><thead><tr><th>Benchmark</th><th>Agent / model</th><th>Resolved</th><th>Tasks</th><th>Evidence</th></tr></thead><tbody>${rows.map(r=>{const sum=summarizeReport(r);return `<tr><td>${esc(BENCHMARKS.find(b=>b.id===r.benchmarkId)?.name)}</td><td>${esc(r.agent)} / ${esc(r.model)}</td><td>${sum.resolved} / ${sum.total}</td><td>${sum.total}</td><td>Unverified import</td></tr>`}).join('')}</tbody></table></div></div>`:`<div class="panel"><p class="muted">No benchmark results imported yet. No fabricated scores are shown.</p></div>`);
}
const views={overview,results,org,gates,pilot,compare,technology,execution,benchmarks,judge,decision:decisionPage,settings};function render(){document.title=`Basis · ${nav.find(x=>x[0]===page)?.[1]}`;$('#app').innerHTML=shell(views[page]());bind();if(page==='settings')bindCredentials();}
function setPath(path,value){let [a,b]=path.split('.');if(a==='meta')s.meta[b]=value;else if(a==='org'){s.org[b]=b==='stack'?value.split(',').map(x=>x.trim()).filter(Boolean):['rate','budget','developers'].includes(b)?Number(value):value;}else if(a==='assumptions')s.assumptions[b]=Number(value);save();}
function addModal(name,fields,callback){const wrap=document.createElement('div');wrap.className='modalback';wrap.innerHTML=`<form class="modal"><div class="modalhead"><h2>${esc(name)}</h2><button type="button" class="iconbtn" data-close aria-label="Close">${icon('cross',18)}</button></div>${fields.map(x=>`<label>${x.label}${x.type==='select'?`<select name="${x.name}">${x.options.map(v=>`<option value="${esc(v[0])}">${esc(v[1])}</option>`).join('')}</select>`:x.type==='textarea'?`<textarea name="${x.name}" required></textarea>`:`<input name="${x.name}" type="${x.type||'text'}" ${x.required===false?'':'required'} ${x.min!=null?`min="${x.min}"`:''} value="${esc(x.value??'')}">`}</label>`).join('')}<div class="modalbuttons"><button type="button" data-close class="secondary">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;document.body.append(wrap);wrap.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>wrap.remove());wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));callback(obj);wrap.remove();save();render();};wrap.querySelector('input,select,textarea')?.focus();}
function act(a,el){if(a==='open-fixture-actions'||a==='open-run-secrets'){
 const repo=$('#evaluation-repo').value.trim();const guidance=$('#run-guidance');
 if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)){guidance.textContent='Enter your GitHub repository above in owner/repository format.';$('#evaluation-repo').focus();return}
 localStorage.setItem('basis-evaluation-repo',repo);
 window.open(`https://github.com/${repo}/${a==='open-run-secrets'?'settings/secrets/actions':'actions/workflows/agent-benchmark.yml'}`,'_blank','noopener,noreferrer');
 guidance.textContent=a==='open-run-secrets'?'Add the matching provider key in GitHub, then open the test workflow.':'In GitHub, choose Run workflow, select the agent, and confirm the public fixture.';
}else if(a==='menu'){drawer=!drawer;render()}else if(a==='import-benchmark'){$('#benchmark-file').click()}else if(a==='download-benchmark-template'){const data={type:'basis-community-benchmark-report',schemaVersion:1,benchmarkId:'swebench-lite',datasetRevision:'REPLACE_WITH_40_CHAR_COMMIT',harnessRevision:'REPLACE_WITH_40_CHAR_COMMIT',agent:'REPLACE',model:'REPLACE',executionMode:'CLI',runId:'REPLACE',provenance:'external-official-harness',verified:false,humanAccepted:false,tasks:[]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),l=document.createElement('a');l.href=u;l.download='basis-benchmark-report-template.json';l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}else if(a==='import-agent'){$('#agent-file').click()}else if(a==='assistant'){
 const wrap=document.createElement('div');wrap.className='modalback';
 wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="modalhead"><h2 id="help-title">How to use Basis</h2><button class="iconbtn" aria-label="Close">${icon('cross',18)}</button></div><p class="muted">Start with a small test to learn the workflow. You can add team context and more detailed evaluation criteria later.</p><ol class="help-steps"><li><b>Set up</b><p>Optional team context, requirements, and your own pilot tasks.</p></li><li><b>Run tests</b><p>Add a provider key in your GitHub repository, start a workflow there, then import its result here.</p></li><li><b>Results</b><p>Review imported checks and pilot observations. They remain separate evidence sources.</p></li></ol><p class="panelnote">Basis stores data in this browser. It does not run agents, monitor jobs, or retrieve results automatically.</p><button class="primary" data-help-start>Go to the small test</button></section>`;
 document.body.append(wrap);const close=()=>wrap.remove();wrap.querySelector('.iconbtn').onclick=close;wrap.onclick=e=>{if(e.target===wrap)close()};wrap.onkeydown=e=>{if(e.key==='Escape')close()};wrap.querySelector('[data-help-start]').onclick=()=>{close();page='execution';drawer=false;render();window.scrollTo(0,0)};wrap.querySelector('.iconbtn').focus();
}else if(a==='export'){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),l=document.createElement('a');l.href=url;l.download='basis-study.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a==='import'){$('#file-input').click()}else if(a==='reset'){if(confirm('Start a new, empty study? This replaces your local data.')){s=clone(demo);selected='claude';save();note('Empty study created')}}else if(a==='manage-platforms'){addModal('Add coding platform',[{name:'name',label:'Platform name'},{name:'provider',label:'Provider / vendor'},{name:'mode',label:'Execution mode (IDE, CLI, autonomous, API)'},{name:'model',label:'Model/version under test'}],v=>{const id='p'+Date.now();s.platforms.push({id,...v,enabled:true});s.gateResults[id]={};})}else if(a==='clear-demo'){if(confirm('Remove all synthetic pilot runs? This cannot be undone without a saved export.')){s.runs=[];s.meta.demo=false;save();note('Synthetic results cleared; begin collecting actual evidence')}}else if(a==='add-task'){addModal('Add benchmark task',[{name:'name',label:'Task name'},{name:'type',label:'Work type',type:'select',options:TYPES.map(x=>[x,x])},{name:'difficulty',label:'Difficulty',type:'select',options:[['easy','Easy'],['medium','Medium'],['hard','Hard']]},{name:'acceptance',label:'Independent acceptance criteria'},{name:'baseline',label:'Baseline human minutes',type:'number',min:0,value:60}],v=>s.tasks.push({id:'T-'+Date.now().toString().slice(-7),...v,baseline:Number(v.baseline)}))}else if(a==='add-run'){addModal('Record a pilot result',[{name:'platform',label:'Platform',type:'select',options:s.platforms.map(x=>[x.id,x.name])},{name:'task',label:'Benchmark task',type:'select',options:s.tasks.map(x=>[x.id,x.name])},{name:'accepted',label:'Accepted by independent criteria?',type:'select',options:[['yes','Yes'],['no','No']]},{name:'humanMinutes',label:'Total human effort (minutes)',type:'number',min:0,value:60},{name:'usageCost',label:'Tool usage cost ($)',type:'number',min:0,value:5},{name:'evidence',label:'Evidence URL',required:false},{name:'notes',label:'Reviewer notes',type:'textarea',required:false}],v=>s.runs.push({id:'R-'+Date.now(),platform:v.platform,task:v.task,accepted:v.accepted==='yes',humanMinutes:Number(v.humanMinutes),usageCost:Number(v.usageCost),evidence:v.evidence,notes:v.notes,source:'Manual record',quality:v.accepted==='yes'?4:2,review:3,stability:3,date:new Date().toISOString().slice(0,10)}))}else if(a==='add-gate'){addModal('Add organization requirement',[{name:'name',label:'Required control'},{name:'required',label:'Classification',type:'select',options:[['yes','Mandatory'],['no','Advisory']]}],v=>s.gates.push({id:'g'+Date.now(),name:v.name,required:v.required==='yes'}))}else if(a==='add-judgment'){addModal('Add blind judge comparison',[{name:'caseName',label:'Masked evaluation case'},{name:'scoreA',label:'Independent judge A (1–5)',type:'number',min:1,value:3},{name:'scoreB',label:'Independent judge B (1–5)',type:'number',min:1,value:3},{name:'review',label:'Human reviewer outcome',required:false}],v=>s.judgments.push({id:'J'+Date.now(),caseName:v.caseName,scoreA:Number(v.scoreA),scoreB:Number(v.scoreB),review:v.review}))}else if(a==='delete-task'){if(confirm('Delete this task and its associated runs?')){s.tasks=s.tasks.filter(x=>x.id!==el.dataset.id);s.runs=s.runs.filter(x=>x.task!==el.dataset.id);save();render()}}else if(a==='delete-run'){if(confirm('Delete this result?')){s.runs=s.runs.filter(x=>x.id!==el.dataset.id);save();render()}}else if(a==='delete-gate'){if(confirm('Remove this requirement?')){s.gates=s.gates.filter(x=>x.id!==el.dataset.id);save();render()}}else if(a==='toggle-details'){details=!details;render()}else if(a==='mark-real'){alert('To create a real study, first choose Clear synthetic results in Pilot studio. Demonstration runs cannot be promoted to genuine evidence.');}}
function bind(){const repoInput=$('#evaluation-repo');if(repoInput)repoInput.onchange=()=>localStorage.setItem('basis-evaluation-repo',repoInput.value.trim());if(document.querySelector('.swe-studio')){
 const read=()=>{let pct=Number(document.querySelector('#swe-custom').value);if(!Number.isInteger(pct)||pct<1||pct>100)return null;const agents=[...document.querySelectorAll('[data-swe-agent]:checked')].map(x=>x.dataset.sweAgent);return {percent:pct,seed:document.querySelector('#swe-seed').value||'42',agents,repo:document.querySelector('#swe-repo').value.trim()}};
 const sync=()=>{let c=read();if(!c)return;localStorage.setItem('basis-swe-config',JSON.stringify(c));document.querySelector('#swe-count').textContent=`${Math.ceil(c.percent*3)} of 300 tasks · repo-balanced nested sample`;document.querySelectorAll('[data-swe-pct]').forEach(b=>b.classList.toggle('active',Number(b.dataset.swePct)===c.percent))};
 document.querySelectorAll('[data-swe-pct]').forEach(b=>b.onclick=()=>{document.querySelector('#swe-custom').value=b.dataset.swePct;sync()});
 document.querySelectorAll('.swe-studio input').forEach(el=>el.addEventListener('change',sync));
 document.querySelector('[data-act="open-swe-actions"]').onclick=()=>{const c=read();if(!c||!c.agents.length){alert('Select at least one agent and a valid sample percentage.');return}if(!/^[\w.-]+\/[\w.-]+$/.test(c.repo)){alert('Enter a valid GitHub repository owner/name.');return}sync();window.open(`https://github.com/${c.repo}/actions/workflows/swebench-lite.yml`,'_blank','noopener,noreferrer');document.querySelector('#swe-guidance').textContent=`In GitHub Actions choose Run workflow: percent=${c.percent}, seed=${c.seed}, agents=${c.agents.join(',')}. Confirm expected API and CI charges.`};
 document.querySelector('[data-act="download-swe-config"]').onclick=()=>{let c=read();if(!c||!c.agents.length){alert('Choose valid settings and at least one agent');return}const blob=new Blob([JSON.stringify({type:'basis-swebench-lite-run-config',...c},null,2)],{type:'application/json'});let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='basis-swebench-lite-run.json';a.click();URL.revokeObjectURL(u)};
}document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;drawer=false;render();window.scrollTo(0,0)});document.querySelectorAll('[data-act]').forEach(b=>{if(!['open-swe-actions','download-swe-config'].includes(b.dataset.act))b.onclick=()=>act(b.dataset.act,b)});document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{sub=b.dataset.sub;render()});document.querySelectorAll('[data-platform]').forEach(b=>b.onclick=()=>{selected=b.dataset.platform;render()});document.querySelectorAll('[data-path]').forEach(el=>el.onchange=()=>{setPath(el.dataset.path,el.value);render()});document.querySelectorAll('[data-weight]').forEach(el=>el.onchange=()=>{s.weights[el.dataset.weight]=Math.max(0,Number(el.value)||0);save();render()});document.querySelectorAll('[data-mix]').forEach(el=>el.oninput=()=>{s.mix[el.dataset.mix]=Number(el.value);save();$(`[data-mix-label="${el.dataset.mix}"]`).textContent=el.value+'%';$('#mixnote').textContent='Normalized for comparison: '+Object.values(s.mix).reduce((a,b)=>a+Number(b),0)+'% entered (automatically normalized).'});document.querySelectorAll('[data-gate]').forEach(el=>el.onchange=()=>{const [p,g]=el.dataset.gate.split(':');s.gateResults[p]??={};s.gateResults[p][g]=el.value;save();render()});document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filter=el.value;render()});document.querySelectorAll('[data-range]').forEach(el=>el.oninput=()=>{setPath(el.dataset.range,el.value);render()});if($('#benchmark-file'))$('#benchmark-file').onchange=async e=>{try{const r=validateBenchmarkReport(JSON.parse(await e.target.files[0].text()));let reports=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]');reports=reports.filter(x=>!(x.benchmarkId===r.benchmarkId&&x.runId===r.runId&&x.agent===r.agent));reports.push(r);localStorage.setItem('basis-community-benchmark-imports',JSON.stringify(reports));note('Benchmark report imported — unverified provenance')}catch(err){alert('Cannot import benchmark report: '+err.message)}};if($('#agent-file'))$('#agent-file').onchange=async e=>{try{let r=JSON.parse(await e.target.files[0].text());if(r.provenance?.toLowerCase().includes('mock')||r.candidate==='mock')throw Error('Mock evidence is not permitted in production');if(r.type!=='basis-agent-evaluation'||r.schemaVersion!==2||!['claude','cursor','codex','opencode'].includes(r.candidate)||typeof r.automatedTestsPass!=='boolean'||r.accepted!==false||!/^([a-f0-9]{64})$/.test(r.taskDigest))throw Error('Unrecognized or invalid execution schema');localStorage.setItem('basis-latest-agent-result',JSON.stringify(r));note('Automated run imported: human review still required')}catch(err){alert('Cannot import: '+err.message)}};$('#file-input').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!validateState(data))throw Error('Not a Basis study');if(data.meta?.demo||data.runs.some(r=>/illustrative|synthetic|mock/i.test([r.source,r.notes,r.recordKind,r.candidate].join(' '))))throw Error('Demonstration or mock data cannot be imported into production');if(!confirm('Replace the current workspace with the imported study?'))return;s=data;save();note('Study imported as user-provided, unverified evidence')}catch(err){alert('Import failed: '+err.message)}}}
render();
